options.content:
{{#if (eq user_is_admin 0)}}
  <style>
    /* Non-admins see the notice only: hide every other panel on this dashboard.
       Scoped inside the panel, so it disappears with the panel on navigation. */
    .react-grid-item:not(:has(#h360-access-denied)),
    [data-viz-panel-key]:not(:has(#h360-access-denied)) {
      display: none !important;
    }
  </style>
  <div id="h360-access-denied" style="color: #e02424; background: rgba(224, 36, 36, 0.05); border-left: 4px solid #e02424; padding: 8px 14px; font-size: 13px; display: flex; align-items: center; gap: 8px; border-radius: 2px; line-height: 1.4;">
    <span>⚠️</span>
    <span><strong>Access Denied:</strong> You must be an admin to view this page.</span>
  </div>
{{/if}}

options.styles:
.h3-card {
  background: #ffffff;
  border-radius: 12px;
  border: 1px solid rgba(128,128,128,0.25);
  padding: 16px 24px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  height: 100%;
}
.h3-card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 8px;
}
.h3-card-icon {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.h3-icon-status { background: rgba(59, 130, 246, 0.1); color: #3b82f6; }
.h3-icon-clock { background: rgba(139, 92, 246, 0.1); color: #8b5cf6; }
.h3-icon-check { background: rgba(16, 185, 129, 0.1); color: #10b981; }
.h3-card-title {
  font-size: 13px;
  font-weight: 600;
  color: #6b7280;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.h3-card-value {
  font-size: 26px;
  font-weight: 700;
  color: #111827;
}

options.afterRender:
if (!document.getElementById('custom-table-header-style')) {
  const style = document.createElement('style');
  style.id = 'custom-table-header-style';
  style.innerHTML = `
    div[role="columnheader"] *, 
    th[role="columnheader"] *, 
    [class*="-table-header"] *,
    div[role="columnheader"], 
    th[role="columnheader"], 
    [class*="-table-header"] {
      color: #000000 !important;
      font-weight: 800 !important;
    }
  `;
  document.head.appendChild(style);
}
const el = context.element || context.grafana?.element;
if (!el) return;
const statusEl = el.querySelector('#h3-val-status');
if (statusEl) {
  const status = statusEl.textContent.trim().toLowerCase();
  if (status === 'success') {
    statusEl.style.color = '#10b981';
    statusEl.textContent = 'Success';
  } else if (status === 'failed') {
    statusEl.style.color = '#ef4444';
    statusEl.textContent = 'Failed';
  } else {
    statusEl.style.color = '#6b7280';
    statusEl.style.fontSize = '20px';
  }
}

